const r = await tools.exec_command({cmd:"python - <<'PY'
import csv,collections,ast,datetime,calendar
E={x['PESEL']:x for x in csv.DictReader(open('/app/dataset/employees.csv'))}
T={int(x['task_id']):int(x['pay_per_completion']) for x in csv.DictReader(open('/app/dataset/tasks.csv'))}
rows=list(csv.DictReader(open('/app/dataset/timesheet.csv')))
def calc(mode):
 totals=collections.defaultdict(int); counts=collections.Counter()
 for x in rows:
  p=x['employee_id']
  if p not in E: continue
  y,m,d=map(int,x['date'].split('-'))
  dim=calendar.monthrange(y,m)[1]
  if d>dim:
   if mode=='exclude': continue
   d=dim
  dt=datetime.date(y,m,d)
  if mode=='calendar': k=dt.strftime('%Y-%m')
  else:
   # first occurrence in calendar month of dataset min weekday
   wd=1 # Tuesday Python Mon=0
   startday=1+(wd-datetime.date(y,m,1).weekday())%7
   start=datetime.date(y,m,startday)
   if dt<start:
    if m==1:y2,m2=y-1,12
    else:y2,m2=y,m-1
    stday=1+(wd-datetime.date(y2,m2,1).weekday())%7
    k=datetime.date(y2,m2,stday).strftime('%Y-%m')
   else:k=start.strftime('%Y-%m')
  try:tasks=ast.literal_eval(x['performed_tasks'])
  except Exception: tasks=[]
  bonus=sum(T.get(int(t),0) for t in tasks if str(t).lstrip('-').isdigit())
  totals[p,k]+=int(x['hours_worked'])*int(float(E[p]['hourly_rate']))+bonus
  counts[p,k]+=1
 keys=sorted(set(k for p,k in totals))
 out={p:[totals[p,k] for k in keys] for p in E}
 print('\nMODE',mode,'keys',keys,'rows considered',sum(counts.values()),'sum',sum(sum(v) for v in out.values()))
 print('month row counts',collections.Counter(k for p,k in counts for _ in range(counts[p,k])))
 print('all four counts?',[(p,[counts[p,k] for k in keys]) for p in E if any(counts[p,k]==0 for k in keys)])
 return out
for mode in ['cycle','exclude','calendar']:
 out=calc(mode)
 if mode=='cycle':
  for p,v in out.items():print(p,v)
PY",yield_time_ms:10000,max_output_tokens:5000});
